# owner: platform
"""Seating charts laid out as printable rows."""

from typing import Iterable, List

from rosterkit.models import Student


def _by_last_name(student: Student) -> tuple:
    return (student.last_name.lower(), student.first_name.lower())


def _row_line(number: int, members: List[Student]) -> str:
    names = " | ".join(item.display_name for item in members)
    return f"Row {number}: {names}"


# ---
def seating_rows(students: Iterable[Student], seats_per_row: int) -> List[str]:
    """One line of text per row, students sorted by last name."""
    if seats_per_row <= 0:
        raise ValueError(f"seats_per_row must be positive: {seats_per_row}")
    ordered = sorted(students, key=_by_last_name)
    if not ordered:
        raise ValueError("no students to seat")
    return [
        _row_line(index // seats_per_row + 1, ordered[index : index + seats_per_row])
        for index in range(0, len(ordered), seats_per_row)
    ]
